import a from "./parts/a.mjs";
import b from "./parts/b.mjs";
import c from "./parts/c.mjs";
import d from "./parts/d.mjs";
import e from "./parts/e.mjs";

export default function summarize() {
  const parts = [a, b, c, d, e];
  const sum = parts.reduce((acc, part) => acc + part.value, 0);
  return {
    parts,
    summary: `esm-graph/${parts.length}/${sum}/phase9`,
  };
}
